Q: How to get the elements from a table after all components are rendered? A: <p>The issue Is that your test is trying to access the DOM elements before the <code>useEffect</code> hook in <code>UsersTable</code> has completed fetching and rendering the data.</p>
<p>You can use reacts <code>@testing-library</code>'s <code>findBy</code> or <code>waitFor</code> methods to wait for the components to render your component data asynchronously.</p>
<pre><code>import { render, screen, waitFor } from '@testing-library/react';
import React from 'react';
import { BrowserRouter as Router } from 'react-router-dom';
import '@testing-library/jest-dom/extend-expect';
import UsersTable from '../components/users/UserTable';


jest.mock('api', () =&gt; ({ // Mocking fetch user API call
    fetchUsers: jest.fn(() =&gt;
        Promise.resolve(
            Array.from({ length: 192 }, (_, i) =&gt; ({
                id: i + 1,
                fullName: `User ${i + 1}`,
                email: `user${i + 1}@example.com`,
            }))
        )
    ),
}));

test('Test #1: Count Users', async () =&gt; {
    render(
        &lt;Router&gt;
            &lt;UsersTable /&gt;
        &lt;/Router&gt;
    );

    // Waiting for the rows to rendered including the header row
    await waitFor(() =&gt; { 
        expect(screen.getAllByRole('row').length).toBe(193);
    });
});
</code></pre>
<p>This will guarantee asynchronous rendering and avoid querying before the data is available.</p>

